-- m47: Pedras de Evolução por cadeias de quests com NPCs (dados editáveis pelo Mestre).
insert into public.itens (slug, nome, categoria, efeito, arco) values
 ('fire-stone','Pedra do Fogo','evolucao',null,1),('water-stone','Pedra da Água','evolucao',null,1),('thunder-stone','Pedra do Trovão','evolucao',null,1),
 ('leaf-stone','Pedra da Folha','evolucao',null,1),('moon-stone','Pedra da Lua','evolucao',null,1)
on conflict (slug) do nothing;

create table if not exists public.pedra_cadeias (id text primary key, pedra text not null references public.itens (slug), nome text not null, preco int not null default 800, ativa boolean not null default true);
create table if not exists public.pedra_etapas (
  id text primary key, cadeia text not null references public.pedra_cadeias (id) on delete cascade, ordem int not null,
  mapa_id text not null, x int not null, y int not null, direcao text not null default 'baixo',
  nome text not null, classe text not null default 'Morador', aparencia smallint not null default 0,
  tipo text not null check (tipo in ('coletar','falar','final')), falas jsonb not null default '{}'::jsonb, unique (cadeia, ordem)
);
create table if not exists public.pedra_progresso (jogador uuid not null references public.jogadores (id) on delete cascade, cadeia text not null references public.pedra_cadeias (id) on delete cascade, etapa int not null default 0, primary key (jogador, cadeia));
alter table public.pedra_cadeias enable row level security; alter table public.pedra_etapas enable row level security; alter table public.pedra_progresso enable row level security;
drop policy if exists pc_leitura on public.pedra_cadeias; create policy pc_leitura on public.pedra_cadeias for select to authenticated using (true);
drop policy if exists pe_leitura on public.pedra_etapas; create policy pe_leitura on public.pedra_etapas for select to authenticated using (true);
drop policy if exists pp_leitura on public.pedra_progresso; create policy pp_leitura on public.pedra_progresso for select to authenticated using (jogador = auth.uid());
grant select on public.pedra_cadeias, public.pedra_etapas, public.pedra_progresso to authenticated;
insert into public.pedra_cadeias (id, pedra, nome, preco) values ('fogo','fire-stone','Pedra do Fogo',800) on conflict (id) do update set pedra=excluded.pedra, nome=excluded.nome, preco=excluded.preco;
