create or replace function public.pedra_interagir(p_npc text) returns jsonb language plpgsql security definer set search_path = public as $$
declare e public.pedra_etapas; c public.pedra_cadeias; pr int; din int;
begin
  if auth.uid() is null then raise exception 'Faça login primeiro.'; end if;
  select * into e from public.pedra_etapas where id = p_npc;
  if not found then raise exception 'NPC inválido.'; end if;
  select * into c from public.pedra_cadeias where id = e.cadeia and ativa;
  if not found then return jsonb_build_object('res', 'inativa', 'nome', e.nome, 'texto', 'Hoje não tenho nada a dizer.'); end if;
  insert into public.pedra_progresso (jogador, cadeia) values (auth.uid(), c.id) on conflict do nothing;
  select etapa into pr from public.pedra_progresso where jogador = auth.uid() and cadeia = c.id for update;
  if e.ordem = pr + 1 then
    if e.tipo = 'final' then
      select dinheiro into din from public.jogadores where id = auth.uid() for update;
      if din < c.preco then return jsonb_build_object('res', 'sem_dinheiro', 'nome', e.nome, 'texto', e.falas->>'sem_dinheiro', 'preco', c.preco); end if;
      update public.jogadores set dinheiro = dinheiro - c.preco where id = auth.uid();
      insert into public.inventario (jogador, item, qtd) values (auth.uid(), c.pedra, 1) on conflict (jogador, item) do update set qtd = public.inventario.qtd + 1;
      update public.pedra_progresso set etapa = 0 where jogador = auth.uid() and cadeia = c.id;
      return jsonb_build_object('res', 'concluida', 'nome', e.nome, 'texto', e.falas->>'ini', 'item', c.pedra, 'pedra', c.nome, 'preco', c.preco);
    end if;
    update public.pedra_progresso set etapa = e.ordem where jogador = auth.uid() and cadeia = c.id;
    return jsonb_build_object('res', 'avanca', 'nome', e.nome, 'texto', e.falas->>'ini', 'pedra', c.nome, 'tipo', e.tipo);
  elsif e.ordem <= pr then
    return jsonb_build_object('res', 'feito', 'nome', e.nome, 'texto', e.falas->>'feito');
  end if;
  return jsonb_build_object('res', 'cedo', 'nome', e.nome, 'texto', coalesce(nullif(e.falas->>'cedo', ''), 'Não sei do que fala... ainda.'));
end $$;
revoke all on function public.pedra_interagir(text) from public, anon;
grant execute on function public.pedra_interagir(text) to authenticated;
